export function quote({ subtotalCents, region, speed, coupon, member, weightGrams }) {
  if (!Number.isInteger(subtotalCents) || subtotalCents < 0) throw new RangeError('subtotal');
  if (!Number.isInteger(weightGrams) || weightGrams < 0) throw new RangeError('weight');
  if (region !== 'metro' && region !== 'interior') throw new RangeError('region');
  if (speed !== 'standard' && speed !== 'express') throw new RangeError('speed');

  if (speed === 'standard' && region === 'metro') {
    if (subtotalCents >= 8000 || coupon === 'FRETEGRATIS') return 0;
    let fee = 900;
    if (weightGrams > 2000) fee += 400;
    if (member) fee -= 300;
    return fee;
  } else if (speed === 'standard' && region === 'interior') {
    if (subtotalCents >= 12000 || coupon === 'FRETEGRATIS') return 0;
    let fee = 1500;
    if (weightGrams > 2000) fee += 400;
    if (member) fee -= 300;
    return fee;
  } else if (speed === 'express' && region === 'metro') {
    let fee = 1900;
    if (weightGrams > 2000) fee += 700;
    if (member) fee -= 300;
    return fee;
  } else {
    let fee = 2600;
    if (weightGrams > 2000) fee += 700;
    if (member) fee -= 300;
    return fee;
  }
}
